import{_ as e,a0 as s,w as u,s as p,ao as a,I as t,x as i,a1 as n,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"Linux命令行中的幽默 | LCTT x X-CMD","titleTemplate":false,"description":"Linux命令行中的幽默 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux命令行中的幽默 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux命令行中的幽默 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150616 Linux Humor on the Command-line","title":"Linux命令行中的幽默","tag":"201507","desc":""},"relativePath":"201507/20150616 Linux Humor on the Command-line.md","filePath":"[post].md"}'),m={name:"201507/20150616 Linux Humor on the Command-line.md"};function d(w,l,x,g,f,T){const o=s("Link");return u(),p("div",null,[l[25]||(l[25]=a('<h1 id="linux命令行中的幽默" tabindex="-1">Linux命令行中的幽默 <a class="header-anchor" href="#linux命令行中的幽默" aria-label="Permalink to “Linux命令行中的幽默”">​</a></h1><p>图形桌面总是很养眼的，它增强了可视化体验，有时也能够提升了某些软件的功能，让软件变得更有趣。但是，在命令行下工作也不需要总是很古板，如果您想在命令行下寻找些乐趣，那么有很多命令给您带来趣味。</p><p>Linux是个有趣的操作系统。它提供大量的小型开源工具，从平淡无奇的软件到稀奇古怪的应用。正是这些工具的功能和琳琅满目的选择帮助Linux脱颖而出。让我们一起来看看下面这七个小工具吧。</p><h3 id="七彩虹-lolcat" tabindex="-1">七彩虹：lolcat <a class="header-anchor" href="#七彩虹-lolcat" aria-label="Permalink to “七彩虹：lolcat”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Misc/Screenshot-lolcat.png" alt="lolcat"></p><p>lolcat是一个用于将文件或标准输入连接到标准输出（类似常见的cat）的程序，但是它会为输出添加七彩的颜色。</p><p>lolcat通常和其他诸如toilet或figlet等生成文本的应用结合使用。这个软件不应被误认为是一个或多个猫的图像的宏。</p><p>lolcat由Moe编写。</p>',8)),t("p",null,[l[1]||(l[1]=i("网址: ",-1)),n(o,{href:"https://github.com/busyloop/lolcat"},{default:r(()=>[...l[0]||(l[0]=[i("github.com",-1)])]),_:1})]),l[26]||(l[26]=a('<h3 id="牛郎的牛-cowsay" tabindex="-1">牛郎的牛：cowsay <a class="header-anchor" href="#牛郎的牛-cowsay" aria-label="Permalink to “牛郎的牛：cowsay”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Misc/Screenshot-cowsay.png" alt="cowsay"></p><p>cowsay是一个可配置的开源软件，它用ASCII码生成奶牛的图片，并可以在对话气泡中显示消息。cowsay是用Perl写的。</p><p>cowsay并不仅仅只能显示奶牛。它能生成预先制作的图片或者其他动物，包括鸭子、考拉、麋鹿、小马、绵羊、剑龙和火鸡，以及奶酪、雪人和骷髅。</p><p>有一个叫cowthink的应用，与对话的气泡不同，它能在生成奶牛的同时生成思考的气泡。</p><p>功能包括：</p><ul><li>让脚本变得更有趣</li><li>Borg模式</li><li>可以更改奶牛看起来的样子，比如让奶牛看起来贪婪、偏执、固执、疲倦、古怪、年轻等</li><li>图形版变体：xcowsay</li></ul>',7)),t("p",null,[l[3]||(l[3]=i("网址: ",-1)),n(o,{href:"https://web.archive.org/web/20120225123719/http://www.nog.net/%7Etony/warez/cowsay.shtml"},{default:r(()=>[...l[2]||(l[2]=[i("nog.net",-1)])]),_:1})]),l[27]||(l[27]=a('<h3 id="傻狗-doge" tabindex="-1">傻狗：doge <a class="header-anchor" href="#傻狗-doge" aria-label="Permalink to “傻狗：doge”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Misc/Screenshot-doge.png" alt="doge"></p><p>doge是一个简单的每日信息脚本，它基于有些愚蠢但很有趣的doge的梗。它随机的打印一些在语法上有误的句子，有时这些句子基于您电脑中的东西。</p><p>doge是一个在2013年非常流行的互联网潮流元素（梗）。这个梗通常由一幅日本柴犬的图片和彩色的文字组成。这些文字故意用一种蹩脚的语气写成了一些互联网的独白。</p><ul><li>随机的用不同的颜色和蹩脚的英语写下随机的句子</li><li>终端中的柴犬效果非常棒</li><li>可以获得系统数据，比如主机名、运行中的程序、当前用户、$EDITOR</li><li>如果您安装了lolcat，您可以用它作为点缀: <code>while true; do doge | lolcat -a -d 100 -s 100 -p 1; done</code></li><li>支持标准输入: <code>ls /usr/bin | doge</code> 将显示一些 /usr/bin下的可执行文件。哇噢，还有许多命令行的开关可以过滤词语以及控制词语的频率。</li></ul>',5)),t("p",null,[l[5]||(l[5]=i("网址: ",-1)),n(o,{href:"https://github.com/thiderman/doge"},{default:r(()=>[...l[4]||(l[4]=[i("github.com/thiderman/doge",-1)])]),_:1})]),l[28]||(l[28]=a('<h3 id="水族箱-asciiquarium" tabindex="-1">水族箱：ASCIIQuarium <a class="header-anchor" href="#水族箱-asciiquarium" aria-label="Permalink to “水族箱：ASCIIQuarium”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Misc/Screenshot-Asciiquarium.png" alt="Asciiquarium"></p><p>ASCIIQuarium是一个以ASCII码方式画出的水族馆/海洋动画。享受生活在您电脑中水底的奇妙生物吧。</p><p>想运行ASCIIQuarium，您需要安装Perl的curses包以及Term::Animation模块。请使用<code>sudo apt-get install libcurses-perl</code>来安装前者，使用sudo cpan Term::Animation来安装后者。两个命令都需要在终端中运行。</p><p>功能包括：</p><ul><li>五彩的鱼儿</li><li>有趣的动画，包括钓鱼钩</li><li>还有许多的天鹅、鸭子、海豚和船只</li></ul>',6)),t("p",null,[l[7]||(l[7]=i("网址: ",-1)),n(o,{href:"http://www.robobunny.com/projects/asciiquarium/html/"},{default:r(()=>[...l[6]||(l[6]=[i("www.robobunny.com",-1)])]),_:1})]),l[29]||(l[29]=t("h3",{id:"蒸汽机车-sl",tabindex:"-1"},[i("蒸汽机车：sl "),t("a",{class:"header-anchor",href:"#蒸汽机车-sl","aria-label":"Permalink to “蒸汽机车：sl”"},"​")],-1)),l[30]||(l[30]=t("p",null,[t("img",{src:"http://www.linuxlinks.com/portal/content/reviews/Misc/Screenshot-sl.png",alt:"sl"})],-1)),l[31]||(l[31]=t("p",null,"sl是一个有趣的终端应用，它为那些意外的错将ls输成sl的用户显示一个动画。",-1)),l[32]||(l[32]=t("p",null,"我打字通常非常草率，更喜欢速度而不是准确性。但错别字在命令行中是非常危险的。因此sl扮演了一个提醒者，提醒我们注意错误输入的这种坏习惯。它总是会让人咯咯的笑。",-1)),l[33]||(l[33]=t("p",null,"功能包括：",-1)),l[34]||(l[34]=t("ul",null,[t("li",null,"使用 -F, 火车在飞翔"),t("li",null,"使用 -l, 显示一个小型的火车"),t("li",null,"使用 -a, 看上去发生了意外")],-1)),t("p",null,[l[9]||(l[9]=i("网址: ",-1)),n(o,{href:"https://github.com/mtoyoda/sl"},{default:r(()=>[...l[8]||(l[8]=[i("github.com/mtoyoda/sl",-1)])]),_:1})]),l[35]||(l[35]=t("h3",{id:"火焰-aafire",tabindex:"-1"},[i("火焰：aafire "),t("a",{class:"header-anchor",href:"#火焰-aafire","aria-label":"Permalink to “火焰：aafire”"},"​")],-1)),l[36]||(l[36]=t("p",null,[t("img",{src:"http://www.linuxlinks.com/portal/content/reviews/Misc/Screenshot-aafire.png",alt:"aafire"})],-1)),l[37]||(l[37]=t("p",null,"aafire在终端中显示燃烧的ASCII火焰。它展示了aalib库的强大能力，一个ascii艺术库显示出来。",-1)),t("p",null,[l[11]||(l[11]=i("网址: ",-1)),n(o,{href:"http://aa-project.sourceforge.net/aalib/"},{default:r(()=>[...l[10]||(l[10]=[i("aa-project.sourceforge.net/aalib",-1)])]),_:1})]),l[38]||(l[38]=a('<h3 id="矩阵-cmatrix" tabindex="-1">矩阵：CMatrix <a class="header-anchor" href="#矩阵-cmatrix" aria-label="Permalink to “矩阵：CMatrix”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Misc/Screenshot-CMatrix.png" alt="CMatrix"></p><p>CMatrix是一个基于ncurses的程序，它模拟《黑客帝国》（一部电影）中的画面。如果您在一个山洞里度过了上个15年，那么您可能不知道这部1999年的美国科幻电影，主角为 Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss, Hugo Weaving和 Joe Pantoliano。</p><p>它可以在终端设置为132x300的情况下工作，并且可以以同样的速率进行滚动或者以用户定义的速度进行异步的滚动。</p><p>功能包括：</p><ul><li>修改文本颜色</li><li>使用粗体字符</li><li>异步滚动</li><li>使用老式的滚动效果</li><li>屏幕保护程序模式</li></ul>',6)),t("p",null,[l[13]||(l[13]=i("网址: ",-1)),n(o,{href:"http://www.asty.org/cmatrix/"},{default:r(()=>[...l[12]||(l[12]=[i("www.asty.org/cmatrix",-1)])]),_:1})]),l[39]||(l[39]=t("hr",null,null,-1)),t("p",null,[l[15]||(l[15]=i("via: ",-1)),n(o,{href:"http://www.linuxlinks.com/article/20150614112018846/Humor.html"},{default:r(()=>[...l[14]||(l[14]=[i("http://www.linuxlinks.com/article/20150614112018846/Humor.html",-1)])]),_:1})]),t("p",null,[l[18]||(l[18]=i("译者：",-1)),n(o,{href:"https://github.com/wwy-hust"},{default:r(()=>[...l[16]||(l[16]=[i("wwy-hust",-1)])]),_:1}),l[19]||(l[19]=i(" 校对：",-1)),n(o,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...l[17]||(l[17]=[i("Caroline",-1)])]),_:1})]),t("p",null,[l[22]||(l[22]=i("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...l[20]||(l[20]=[i("LCTT",-1)])]),_:1}),l[23]||(l[23]=i(" 原创翻译，",-1)),n(o,{href:"https://linux.cn/"},{default:r(()=>[...l[21]||(l[21]=[i("Linux中国",-1)])]),_:1}),l[24]||(l[24]=i(" 荣誉推出",-1))])])}const h=e(m,[["render",d]]);export{S as __pageData,h as default};
